package com.citacloud.app.services;
import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import java.net.URI; import java.net.http.*; import java.time.Duration; import java.util.Map;
@Component public class HttpWhatsappProvider implements WhatsappProvider {private final boolean habilitado;private final String url,token;private final ObjectMapper json;private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(8)).build();public HttpWhatsappProvider(ObjectMapper j,@Value("${app.notifications.whatsapp.configured:false}")boolean h,@Value("${app.notifications.whatsapp.api-url:}")String u,@Value("${app.notifications.whatsapp.token:}")String t){json=j;habilitado=h;url=u;token=t;}public boolean configurado(){return habilitado&&!url.isBlank()&&!token.isBlank();}public Resultado enviar(String d,String m,String tid){if(!configurado())throw new IllegalStateException("WHATSAPP_CHANNEL_NOT_CONFIGURED");try{String body=json.writeValueAsString(Map.of("to",d,"message",m,"templateId",tid==null?"":tid));HttpRequest req=HttpRequest.newBuilder(URI.create(url)).timeout(Duration.ofSeconds(15)).header("Authorization","Bearer "+token).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body)).build();HttpResponse<String> res=http.send(req,HttpResponse.BodyHandlers.ofString());if(res.statusCode()<200||res.statusCode()>299)throw new IllegalStateException("NOTIFICATION_PROVIDER_ERROR_HTTP_"+res.statusCode());return new Resultado("WHATSAPP_HTTP",res.headers().firstValue("x-message-id").orElse(null));}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException("NOTIFICATION_PROVIDER_INTERRUPTED");}catch(Exception e){throw e instanceof IllegalStateException s?s:new IllegalStateException("NOTIFICATION_PROVIDER_ERROR",e);}}}
